WITH thresholds AS (
    SELECT 
        (SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY histsignrating) FROM artifactratings) as hist_thresh,
        (SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY cultscore) FROM artifactratings) as cult_thresh
)
SELECT t.hist_thresh, t.cult_thresh FROM thresholds t;

-- Let me try with OR condition for valuable
WITH ranked AS (
    SELECT artref, NTILE(10) OVER (ORDER BY histsignrating DESC) as hist_tile, NTILE(10) OVER (ORDER BY cultscore DESC) as cult_tile FROM artifactratings
)
SELECT a.artregistry, a.artname, s.insvalueusd, a.conservestatus, s.seclevel FROM artifactscore a JOIN artifactsecurityaccess s ON a.artregistry = s.artref LEFT JOIN ranked r ON a.artregistry = r.artref WHERE (s.insvalueusd > 1000000 OR (r.hist_tile = 1 AND r.cult_tile = 1)) AND a.conservestatus = 'Critical';

-- Try NTILE with ASC ordering (top 10% = highest values = tile 10 when ordered ASC)
WITH ranked AS (
    SELECT artref, NTILE(10) OVER (ORDER BY histsignrating ASC) as hist_tile, NTILE(10) OVER (ORDER BY cultscore ASC) as cult_tile FROM artifactratings
)
SELECT a.artregistry, a.artname, s.insvalueusd, a.conservestatus, s.seclevel FROM artifactscore a JOIN artifactsecurityaccess s ON a.artregistry = s.artref JOIN ranked r ON a.artregistry = r.artref WHERE a.conservestatus = 'Critical' AND r.hist_tile = 10 AND r.cult_tile = 10;

-- Just check all valuable artifacts (top 10% NTILE) regardless of conservation status
WITH ranked AS (
    SELECT artref, NTILE(10) OVER (ORDER BY histsignrating DESC) as hist_tile, NTILE(10) OVER (ORDER BY cultscore DESC) as cult_tile FROM artifactratings
)
SELECT a.artregistry, a.artname, s.insvalueusd, a.conservestatus, s.seclevel FROM artifactscore a JOIN artifactsecurityaccess s ON a.artregistry = s.artref JOIN ranked r ON a.artregistry = r.artref WHERE r.hist_tile = 1 AND r.cult_tile = 1;

-- Maybe "valuable" means insvalueusd is not null (all have values) and we just need conservestatus = 'Critical'
-- But let me also check if there's a relationship between artifactsecurityaccess and conservationandmaintenance
SELECT DISTINCT c.conservesfreq FROM conservationandmaintenance c JOIN artifactscore a ON c.artrefmaintained = a.artregistry WHERE a.conservestatus = 'Critical';

-- Maybe the NTILE should be applied to all artifacts, not just ratings
-- Let me check if there are artifacts without ratings
SELECT COUNT(*) FROM artifactscore WHERE artregistry NOT IN (SELECT artref FROM artifactratings);

WITH rated AS (
    SELECT artref, NTILE(10) OVER (ORDER BY histsignrating DESC) as ht, NTILE(10) OVER (ORDER BY cultscore DESC) as ct FROM artifactratings
)
SELECT a.artregistry, a.artname, s.insvalueusd, a.conservestatus, s.seclevel FROM artifactscore a JOIN artifactsecurityaccess s ON a.artregistry = s.artref WHERE a.conservestatus = 'Critical' AND (s.insvalueusd > 1000000 OR EXISTS (SELECT 1 FROM rated r WHERE r.artref = a.artregistry AND r.ht = 1 AND r.ct = 1));
